const inputData = $input.first().json;
const requestData = inputData.body || inputData;

// Validate required fields
if (!requestData.alert_type || !requestData.title) {
  throw new Error('alert_type and title are required');
}

// Calculate priority score
const priorityScores = {
  critical: 4,
  high: 3,
  medium: 2,
  low: 1
};

const priority = requestData.priority || 'medium';
const priorityScore = priorityScores[priority] || 2;

return [{
  json: {
    company_id: requestData.company_id || null,
    alert_type: requestData.alert_type,
    priority: priority,
    priority_score: priorityScore,
    title: requestData.title,
    description: requestData.description || '',
    data: requestData.data || {},
    action_url: requestData.action_url || null,
    created_at: new Date().toISOString()
  }
}];

const alert = $input.first().json;

// Priority-based emoji and styling
const priorityEmojis = {
  critical: '🚨',
  high: '⚠️',
  medium: 'ℹ️',
  low: '📝'
};

const priorityColors = {
  critical: '#FF0000',
  high: '#FF6600',
  medium: '#3498db',
  low: '#95a5a6'
};

const emoji = priorityEmojis[alert.priority] || 'ℹ️';
const color = priorityColors[alert.priority] || '#3498db';

const slackMessage = {
  channel: alert.priority === 'critical' || alert.priority === 'high' ? '#medtech-critical-alerts' : '#medtech-alerts',
  text: `${emoji} *${alert.title}*`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: `${emoji} ${alert.title}`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: alert.description
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `*Type:* ${alert.alert_type} | *Priority:* ${alert.priority.toUpperCase()} | *Time:* ${new Date(alert.created_at).toLocaleString()}`
        }
      ]
    }
  ],
  attachments: [{
    color: color,
    fields: []
  }]
};

// Add action button if URL provided
if (alert.action_url) {
  slackMessage.blocks.push({
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: 'View Details' },
        url: alert.action_url,
        style: alert.priority === 'critical' ? 'danger' : 'primary'
      }
    ]
  });
}

return [{ json: slackMessage }];
